import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

// Path to precomputed intelligence database generated by python analytics pipeline
const DB_PATH = path.resolve(__dirname, '../../../analytics/data/airfare_intelligence_db.json');
const CLEANED_PATH = path.resolve(__dirname, '../../../analytics/data/cleaned_normalized_flights.json');

let intelligenceData = null;
let cleanedFlightsData = null;

function loadIntelligenceDB() {
  try {
    if (fs.existsSync(DB_PATH)) {
      const raw = fs.readFileSync(DB_PATH, 'utf-8');
      intelligenceData = JSON.parse(raw);
      console.log(`📊 Loaded Airfare Intelligence DB: ${intelligenceData.marketKPIs.totalObservations} records across ${intelligenceData.marketKPIs.totalRoutes} routes.`);
    } else {
      console.warn(`⚠️ Intelligence DB file not found at ${DB_PATH}. Will fallback to static baselines.`);
    }
  } catch (err) {
    console.error('Error reading intelligence DB:', err.message);
  }
}

function loadCleanedFlights() {
  try {
    if (fs.existsSync(CLEANED_PATH)) {
      const raw = fs.readFileSync(CLEANED_PATH, 'utf-8');
      cleanedFlightsData = JSON.parse(raw);
    }
  } catch (err) {
    console.warn('Could not load cleaned flights:', err.message);
  }
}

// Initial load
loadIntelligenceDB();
loadCleanedFlights();

/**
 * Baseline fallback in case JSON DB isn't loaded yet
 */
export const ROUTE_BASELINES = {
  'DEL-BOM': { origin: 'DEL', destination: 'BOM', routeName: 'Delhi to Mumbai', historicalMedian: 5800, volatility: 920 },
  'BOM-DEL': { origin: 'BOM', destination: 'DEL', routeName: 'Mumbai to Delhi', historicalMedian: 5750, volatility: 890 },
  'DEL-BLR': { origin: 'DEL', destination: 'BLR', routeName: 'Delhi to Bengaluru', historicalMedian: 6400, volatility: 1050 },
  'BLR-DEL': { origin: 'BLR', destination: 'DEL', routeName: 'Bengaluru to Delhi', historicalMedian: 6350, volatility: 1020 },
  'BOM-BLR': { origin: 'BOM', destination: 'BLR', routeName: 'Mumbai to Bengaluru', historicalMedian: 4200, volatility: 680 },
  'BLR-BOM': { origin: 'BLR', destination: 'BOM', routeName: 'Bengaluru to Mumbai', historicalMedian: 4150, volatility: 650 },
  'DEL-CCU': { origin: 'DEL', destination: 'CCU', routeName: 'Delhi to Kolkata', historicalMedian: 5600, volatility: 850 },
  'DEL-GOI': { origin: 'DEL', destination: 'GOI', routeName: 'Delhi to Goa', historicalMedian: 6200, volatility: 1180 },
  'DEL-HYD': { origin: 'DEL', destination: 'HYD', routeName: 'Delhi to Hyderabad', historicalMedian: 5200, volatility: 780 },
};

export function getRouteBaseline(origin, destination) {
  const normOrigin = origin.toUpperCase();
  const normDest = destination.toUpperCase();
  const key = `${normOrigin}-${normDest}`;

  if (intelligenceData && intelligenceData.routes && intelligenceData.routes[key]) {
    const r = intelligenceData.routes[key];
    return {
      origin: normOrigin,
      destination: normDest,
      routeName: `${normOrigin} to ${normDest}`,
      historicalMedian: r.historicalMedian,
      historicalMean: r.historicalMean,
      volatility: r.volatility,
      minFare: r.minFare,
      maxFare: r.maxFare,
      bookingWindows: r.bookingWindowCurve.reduce((acc, curr) => {
        acc[curr.windowKey] = curr.medianFare;
        return acc;
      }, {}),
      bookingWindowCurve: r.bookingWindowCurve,
      airlines: r.airlines,
      otas: r.otas,
      anomaliesCount: r.anomaliesCount,
      observationsCount: r.observationsCount,
    };
  }

  // Static fallback
  const fb = ROUTE_BASELINES[key] || { historicalMedian: 5500, volatility: 900 };
  return {
    origin: normOrigin,
    destination: normDest,
    routeName: `${normOrigin} to ${normDest}`,
    historicalMedian: fb.historicalMedian,
    historicalMean: fb.historicalMedian + 100,
    volatility: fb.volatility,
    minFare: Math.round(fb.historicalMedian * 0.65),
    maxFare: Math.round(fb.historicalMedian * 2.1),
    bookingWindows: {
      '0-3': Math.round(fb.historicalMedian * 1.35),
      '4-7': Math.round(fb.historicalMedian * 1.18),
      '8-14': fb.historicalMedian,
      '15-30': Math.round(fb.historicalMedian * 0.9),
      '31-60': Math.round(fb.historicalMedian * 0.85),
      '60+': Math.round(fb.historicalMedian * 0.82),
    },
    bookingWindowCurve: [
      { window: 'Last Minute (0–3 days)', windowKey: '0-3', medianFare: Math.round(fb.historicalMedian * 1.35) },
      { window: 'Short Notice (4–7 days)', windowKey: '4-7', medianFare: Math.round(fb.historicalMedian * 1.18) },
      { window: 'Standard (8–14 days)', windowKey: '8-14', medianFare: fb.historicalMedian },
      { window: 'Advance (15–30 days)', windowKey: '15-30', medianFare: Math.round(fb.historicalMedian * 0.9) },
      { window: 'Early Bird (31–60 days)', windowKey: '31-60', medianFare: Math.round(fb.historicalMedian * 0.85) },
      { window: 'Far Advance (60+ days)', windowKey: '60+', medianFare: Math.round(fb.historicalMedian * 0.82) },
    ],
    airlines: ['IndiGo', 'Air India', 'Vistara', 'Akasa Air'],
    otas: ['MakeMyTrip', 'EaseMyTrip', 'Cleartrip', 'Airline Direct'],
    anomaliesCount: 3,
    observationsCount: 110,
  };
}

export function getBookingWindowDays(departureDate) {
  if (!departureDate) return 14;
  const dep = new Date(departureDate);
  const now = new Date();
  const diffTime = dep - now;
  const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
  return diffDays > 0 ? diffDays : 0;
}

export function getBookingWindowCategory(days) {
  if (days <= 3) return '0-3';
  if (days <= 7) return '4-7';
  if (days <= 14) return '8-14';
  if (days <= 30) return '15-30';
  if (days <= 60) return '31-60';
  return '60+';
}

/**
 * Calculate Airfare Price Index & Anomaly Detection for an offer
 */
export function enrichOfferWithIndex(offer, origin, destination, departureDate) {
  const baseline = getRouteBaseline(origin, destination);
  const fare = Number(offer.price);
  const windowDays = getBookingWindowDays(departureDate);
  const windowCategory = getBookingWindowCategory(windowDays);

  const windowBaselineFare = baseline.bookingWindows[windowCategory] || baseline.historicalMedian;
  const referenceFare = baseline.historicalMedian;

  // Price Index = Current Fare / Reference Fare * 100
  const priceIndex = Math.round((fare / referenceFare) * 100 * 10) / 10;
  const windowIndex = Math.round((fare / windowBaselineFare) * 100 * 10) / 10;

  // Statistical deviation
  const zScore = Math.round(((fare - baseline.historicalMean) / baseline.volatility) * 100) / 100;
  const percentDeviation = Math.round(((fare - referenceFare) / referenceFare) * 100);

  const isAnomaly = zScore > 1.85 || percentDeviation > 40;

  let dealRating = 'FAIR_PRICE';
  let dealLabel = 'Fair Fare';
  let badgeColor = 'blue';

  if (priceIndex <= 85) {
    dealRating = 'GREAT_DEAL';
    dealLabel = 'Exceptional Deal';
    badgeColor = 'emerald';
  } else if (priceIndex <= 95) {
    dealRating = 'GOOD_VALUE';
    dealLabel = 'Good Value';
    badgeColor = 'teal';
  } else if (priceIndex > 125 || isAnomaly) {
    dealRating = 'SURGE_PRICE';
    dealLabel = 'Surge Fare';
    badgeColor = 'amber';
  } else if (priceIndex > 110) {
    dealRating = 'SLIGHTLY_HIGH';
    dealLabel = 'Above Average';
    badgeColor = 'orange';
  }

  return {
    ...offer,
    airfareIndex: {
      priceIndex,
      windowIndex,
      historicalMedian: referenceFare,
      windowAverage: windowBaselineFare,
      bookingWindowDays: windowDays,
      bookingWindowCategory: `${windowCategory} days`,
      percentDeviation,
      zScore,
      isAnomaly,
      anomalyReason: isAnomaly
        ? `Fare ₹${fare.toLocaleString('en-IN')} is +${percentDeviation}% above route median (₹${referenceFare.toLocaleString('en-IN')}) with statistical Z-Score ${zScore}.`
        : null,
      dealRating,
      dealLabel,
      badgeColor,
      savingsAmount: referenceFare > fare ? referenceFare - fare : 0,
    },
  };
}

